#include "ArtifactRuntime.hpp"
namespace elysium::history {bool ArtifactRuntime::promote(Artifact a,std::string&w){if(!a.id||!a.item||!a.definition){w="invalid artifact";return false;}return rows_.emplace(a.id,std::move(a)).second;}bool ArtifactRuntime::transfer(StableId id,ProvenanceEvent e,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown artifact";return false;}if(!e.id||e.from!=i->second.owner){w="invalid provenance transition";return false;}i->second.owner=e.to;i->second.provenance.push_back(e);return true;}std::optional<Artifact>ArtifactRuntime::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
